contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address proposedAddress, string memory typeStr) public payable {
        // require a non-empty type string to avoid ambiguous empty-type proposals
        require(bytes(typeStr).length > 0);

        uint beforeCount = c.proposalCount(); if (__ESBMC_reverted()) return;

        // state-changing call under test
        c.newAddressProposal(proposedAddress, typeStr); if (__ESBMC_reverted()) return;

        uint afterCount = c.proposalCount(); if (__ESBMC_reverted()) return;
        address stored = c.mapPID_address(afterCount); if (__ESBMC_reverted()) return;

        // General rule: count increments by 1 and stored address equals input
        assert(afterCount == beforeCount + 1 && stored == proposedAddress);
    }

    receive() external payable {}
}

