pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(address proposedAddress, string memory typeStr) internal {
        vm.assume(bytes(typeStr).length > 0);
        uint256 beforeCount;
        try c.proposalCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        try c.newAddressProposal(proposedAddress, typeStr) {} catch { return; }
        uint256 afterCount;
        try c.proposalCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        address stored;
        try c.mapPID_address(afterCount) returns (address __r) { stored = __r; } catch { return; }
        assertTrue(afterCount == beforeCount + 1 && stored == proposedAddress);
    }

    function testFuzz_run(address proposedAddress, string memory typeStr) public {
        vm.assume(proposedAddress.code.length == 0 && uint160(proposedAddress) > 0xffff && proposedAddress != address(this) && proposedAddress != address(c) && proposedAddress != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && proposedAddress != 0x000000000000000000636F6e736F6c652e6c6f67 && proposedAddress != 0x4e59b44847b379578588920cA78FbF26c0B4956C && proposedAddress != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(proposedAddress, typeStr);
    }

    receive() external payable {}
}
